from typing import AsyncIterator
import copy
from dataiku.core import dkujson
from dataiku.llm.python.types import CompletionResponse, SimpleCompletionResponse, StreamCompletionResponse, StreamResponseChunkOrFooter
from dataikuapi.dss.llm import DSSLLMStreamedCompletionChunk, DSSLLMStreamedCompletionFooter, DSSLLMCompletionResponse
from dataikuapi.dss.llm_utils import _BaseChunkAggregator, _stream_from_single_response

# For backward-compatibility with older AgentHub, see sc-311296
from dataikuapi.dss.llm_utils import _process_tool_call_chunk as process_tool_call_chunk


def _sanitize_inline_payloads_for_logging(value):
    if value is None:
        return

    if isinstance(value, list):
        for item in value:
            _sanitize_inline_payloads_for_logging(item)
        return

    if not isinstance(value, dict):
        return

    if value.get("type") == "IMAGE_INLINE" and value.get("inlineImage"):
        value["inlineImage"] = "TRUNCATED_INLINE_IMAGE"
    elif value.get("type") == "IMAGE_URI" and value.get("imageUrl", "").startswith("data:"):
        value["imageUrl"] = "data:TRUNCATED_IMAGE_DATA_URI"
    elif value.get("type") == "DATA_INLINE" and value.get("dataBase64"):
        value["dataBase64"] = "TRUNCATED_DATA_INLINE"

    for nested_value in value.values():
        _sanitize_inline_payloads_for_logging(nested_value)


def get_tool_output_safe_for_logging(tool_output):
    redacted_tool_output = copy.deepcopy(tool_output)
    _sanitize_inline_payloads_for_logging(redacted_tool_output)
    return redacted_tool_output


def get_completion_query_safe_for_logging(cq):
    # This should be kept in sync and always "more restrictive" than SingleCompletionQuery.getSafeForLoggingCopy

    redacted_cq = copy.deepcopy(cq)
    _sanitize_inline_payloads_for_logging(redacted_cq.get("messages"))

    # The context has already been printed nicely and redacted by the Java part.
    # Here, just redact everything
    if "context" in cq:
        redacted_cq["context"] = { k : "REDACTED" for k in redacted_cq["context"].keys() }

    return redacted_cq


def parse_single_completion_response(response: CompletionResponse) -> SimpleCompletionResponse:
    # Try to eat anything the user can throw at us

    if isinstance(response, str):
        return {"text": response}

    if isinstance(response, DSSLLMCompletionResponse):
        return response._raw

    if isinstance(response, dict):
        # try to convert other types to str
        text = response.get("text")
        if text is not None and not isinstance(text, str):
            try:
                response["text"] = dkujson.dumps(text)
            except TypeError as exc:
                raise Exception("Invalid type for the text field of the response (%s), it must be a string or an object that can be converted to JSON (%s)" % (type(text), exc))
        return response

    raise Exception("Unrecognized response type (%s), it must be a string, dict or DSSLLMCompletionResponse" % type(response))


def parse_stream_chunk_or_footer(response: StreamCompletionResponse) -> StreamResponseChunkOrFooter:
    # Try to eat anything the user can throw at us

    if isinstance(response, str):
        return {"chunk" : {"type": "content", "text": response}}

    if isinstance(response, DSSLLMStreamedCompletionChunk):
        response.data["type"] = response.data.get("type") or "content"
        return {"chunk" : response.data}

    if isinstance(response, DSSLLMStreamedCompletionFooter):
        response.data["type"] = response.data.get("type") or "footer"
        return {"footer" : response.data}

    if isinstance(response, dict):
        if "chunk" in response or "footer" in response:
            return response
        if "type" in response and response["type"] == "content":
            return {"chunk": response}
        if "type" in response and response["type"] == "footer":
            return {"footer": response}
        if "text" in response or "toolCalls" in response:
            response["type"] = response.get("type") or "content"
            return {"chunk" : response}

    raise Exception("Unrecognized stream response type (%s)" % type(response))


async def single_response_from_stream(stream: AsyncIterator[StreamCompletionResponse]) -> SimpleCompletionResponse:
    aggregator = _BaseChunkAggregator()
    async for res in stream:
        chunk = parse_stream_chunk_or_footer(res)
        aggregator._extract_data_from_chunk(chunk)
    aggregator._build_response()
    return aggregator.response


async def stream_from_single_response(response: CompletionResponse) -> AsyncIterator[StreamResponseChunkOrFooter]:
    parsed_response = parse_single_completion_response(response)

    for chunk_or_footer in _stream_from_single_response(parsed_response):
        yield chunk_or_footer
